"use client"

import {
  Dialog,
  DialogBackdrop as DialogBackdropPrimitive,
  DialogClose as DialogClosePrimitive,
  DialogContent as DialogContentPrimitive,
  DialogDescription as DialogDescriptionPrimitive,
  DialogTitle as DialogTitlePrimitive,
  DialogTrigger as DialogTriggerPrimitive,
  createDialogController,
} from "@ui-sdk/react/dialog"
import { mergeProps, renderElement, type PartProps } from "@ui-sdk/react/primitive"
import { cva, type VariantProps } from "class-variance-authority"
import { useCallback, useRef, type ComponentProps, type ReactNode, type Ref, type RefObject } from "react"

import { buttonVariants, type ButtonLookProps } from "@/components/ui/button"
import { ScrollArea, ScrollAreaScrollbar, ScrollAreaViewport } from "@/components/ui/scroll-area"
import { ControlTooltip } from "@/components/ui/tooltip"
import {
  focusedElement,
  mayReturnFocus,
  useFocusAboveKeyboard,
  useKeepPageStill,
  useRecordFocusMove,
  useRecordOpener,
  type FocusMemory,
} from "@/components/ui/use-dialog-focus"
import { useVisualViewportBox, type ViewportBoxScope } from "@/components/ui/use-dialog-viewport"
import { cn, cnState } from "@/lib/utils"

// While they animate out, the backdrop and content let presses through, so the first click on the page counts.
const backdropClassName =
  "fixed inset-0 z-overlay bg-overlay transition-opacity duration-dialog ease-standard data-ending-style:pointer-events-none data-ending-style:opacity-0 data-starting-style:opacity-0"

// Sizes come from the containing block through %, never viewport units. The content stays in the visible part of the
// page (`useVisualViewportBox`), cut to the containing block: iOS Safari can leave `innerHeight` stale and keep a closed
// keyboard's `offsetTop` with the full height. While the keyboard is up (`data-dialog-keyboard`), which covers the
// layout viewport without resizing it, the content sits on the visible part's bottom edge.
const dialogContentVariants = cva(
  [
    // oxlint-disable-next-line eskais/scroll-area -- the dialog element's fallback for content without a DialogBody, which is the scroll area
    "fixed inset-0 z-overlay m-auto flex h-fit w-(--dialog-width) min-w-0 flex-col gap-group overflow-y-auto overscroll-contain rounded-floating border border-floating-border bg-popover p-inset-surface field-label-surface-popover text-popover-foreground wrap-anywhere shadow-floating outline-none transition duration-dialog ease-standard data-ending-style:pointer-events-none data-ending-style:scale-95 data-ending-style:opacity-0 data-starting-style:scale-95 data-starting-style:opacity-0",
    // oxlint-disable-next-line shadcn/no-arbitrary-values -- no token can read the visual viewport, which useVisualViewportBox sets on the content itself
    "top-[clamp(0px,var(--dialog-viewport-top,0px),100%-var(--dialog-viewport-height,100%))] bottom-[max(0px,100%-var(--dialog-viewport-bottom,100%))] max-h-[min(var(--dialog-max-height),calc(var(--dialog-viewport-height,100%)-2*var(--floating-offset)))]",
    "data-dialog-keyboard:top-auto data-dialog-keyboard:mb-floating",
  ],
  {
    variants: {
      size: {
        sm: "max-w-sm",
        md: "max-w-lg",
        lg: "max-w-3xl",
        xl: "max-w-6xl",
        // oxlint-disable-next-line shadcn/no-arbitrary-values -- no token can read the visual viewport, which useVisualViewportBox sets on the content itself
        full: "h-[min(var(--dialog-max-height),calc(var(--dialog-viewport-height,100%)-2*var(--floating-offset)))] max-w-none",
      },
      sheet: {
        true: [
          "narrow:top-auto narrow:mb-0 narrow:data-dialog-keyboard:mb-0 narrow:h-fit narrow:max-h-[min(var(--sheet-max-height),calc(var(--dialog-viewport-height,100%)-var(--floating-offset)))] narrow:w-full narrow:max-w-none narrow:rounded-b-none narrow:border-b-0 narrow:data-ending-style:translate-y-full narrow:data-ending-style:scale-100 narrow:data-starting-style:translate-y-full narrow:data-starting-style:scale-100 narrow:motion-reduce:data-ending-style:translate-y-0 narrow:motion-reduce:data-starting-style:translate-y-0",
          // The sheet reaches the bottom edge, so it clears the home indicator when the page extends under it
          // (`viewport-fit=cover`); the keyboard covers that edge while it is up.
          "narrow:pb-[max(var(--spacing-inset-surface),env(safe-area-inset-bottom))] narrow:data-dialog-keyboard:pb-inset-surface narrow:data-dialog-flush:pb-[env(safe-area-inset-bottom)] narrow:data-dialog-flush:data-dialog-keyboard:pb-0",
        ].join(" "),
        false: "",
      },
    },
    defaultVariants: { size: "md", sheet: true },
  },
)

/** The default content look (`md`, a bottom sheet on narrow screens), for an AlertDialog or other content part. */
const contentClassName = dialogContentVariants()

type DialogSize = NonNullable<VariantProps<typeof dialogContentVariants>["size"]>

function DialogTrigger({
  className,
  variant = "outline",
  size,
  tooltip,
  ...props
}: Omit<ComponentProps<typeof DialogTriggerPrimitive>, "aria-label"> & ButtonLookProps) {
  return (
    <ControlTooltip label={props["aria-label"]} tooltip={tooltip} iconOnly={size === "icon"}>
      <DialogTriggerPrimitive className={cnState(buttonVariants({ variant, size }), className)} {...props} />
    </ControlTooltip>
  )
}

function DialogBackdrop({ className, ...props }: ComponentProps<typeof DialogBackdropPrimitive>) {
  return <DialogBackdropPrimitive className={cnState(backdropClassName, className)} {...props} />
}

type DialogContentProps = ComponentProps<typeof DialogContentPrimitive> & {
  /** `sm` 24rem, `md` 32rem (default), `lg` 48rem, `xl` 72rem; `full` fills its container less `--floating-offset`. */
  size?: DialogSize
  /** On narrow screens it rises from the bottom as a full-width sheet; `false` keeps it centered. */
  sheet?: boolean
}

type FinalFocus = ComponentProps<typeof DialogContentPrimitive>["finalFocus"]

// Mounts before the content's children, so its layout effect runs before React's `autoFocus` inside them, and
// records the element to return to.
function FocusOpener({ memoryRef }: { memoryRef: RefObject<FocusMemory> }) {
  useRecordOpener(memoryRef)
  return null
}

// Mounts after the children: focus that moved between the two was taken by `autoFocus`, before UI SDK could
// record where it came from (UI SDK 0.1.0-beta.10 then returns focus past the opener, to the next control).
function FocusMoved({ memoryRef }: { memoryRef: RefObject<FocusMemory> }) {
  useRecordFocusMove(memoryRef)
  return null
}

// Mounts with the content, so it follows the keyboard and the page's scroll only while the content is in the page.
function OpenGuards({ contentRef, scope }: { contentRef: RefObject<HTMLElement | null>; scope: ViewportBoxScope }) {
  useVisualViewportBox(contentRef, scope)
  useFocusAboveKeyboard(contentRef)
  useKeepPageStill(contentRef)
  return null
}

function withFocusMarkers(
  content: ReactNode,
  memoryRef: RefObject<FocusMemory>,
  contentRef: RefObject<HTMLElement | null>,
  scope: ViewportBoxScope,
) {
  return (
    <>
      <FocusOpener memoryRef={memoryRef} />
      {content}
      <FocusMoved memoryRef={memoryRef} />
      <OpenGuards contentRef={contentRef} scope={scope} />
    </>
  )
}

function assignRef(ref: Ref<HTMLElement> | undefined, element: HTMLElement | null) {
  if (typeof ref === "function") return ref(element)
  if (ref) ref.current = element
  return undefined
}

function resolveFocusTarget(target: Exclude<FinalFocus, "none">) {
  if (target === undefined || target === "trigger") return null
  if (typeof target === "function") return target()
  if (typeof target === "string") return document.querySelector<HTMLElement>(target)
  return target
}

/**
 * Keeps focus return working where UI SDK misses it (an `autoFocus` field, another modal opening while this one
 * closes), a focused field above the keyboard and the locked page still. Give the content the returned `finalFocus`
 * and `attach` (its ref) and wrap its children. `viewportBox: "parent"` writes the visible box on its parent.
 */
function useFocusReturn(
  finalFocus: FinalFocus,
  forwarded?: Ref<HTMLElement>,
  { viewportBox = "content" }: { viewportBox?: ViewportBoxScope } = {},
) {
  const memoryRef = useRef<FocusMemory>({ opener: null, movedBeforeOpen: false })
  const contentRef = useRef<HTMLElement | null>(null)
  const returnTo = () => {
    const { opener, movedBeforeOpen } = memoryRef.current
    return movedBeforeOpen && opener?.isConnected ? opener : null
  }
  // Returning the focused element leaves focus where it is; null sends UI SDK down its own fallback chain.
  const guarded = () => {
    if (!mayReturnFocus(contentRef.current)) return focusedElement() ?? (document.activeElement as HTMLElement | null)
    return finalFocus === undefined ? returnTo() : resolveFocusTarget(finalFocus as Exclude<FinalFocus, "none">)
  }
  function wrap<State>(children: ReactNode | ((state: State) => ReactNode)) {
    return typeof children === "function"
      ? (state: State) => withFocusMarkers(children(state), memoryRef, contentRef, viewportBox)
      : withFocusMarkers(children, memoryRef, contentRef, viewportBox)
  }
  const attach = useCallback(
    (element: HTMLElement | null) => {
      contentRef.current = element
      return assignRef(forwarded, element)
    },
    [forwarded],
  )
  return { finalFocus: finalFocus === "none" ? finalFocus : guarded, wrap, attach }
}

function DialogContent({
  className,
  size = "md",
  sheet = true,
  finalFocus,
  ref,
  children,
  ...props
}: DialogContentProps) {
  const { attach, finalFocus: returnFocus, wrap } = useFocusReturn(finalFocus, ref as Ref<HTMLElement> | undefined)
  return (
    <DialogContentPrimitive
      ref={attach}
      data-size={size}
      data-sheet={sheet ? "" : undefined}
      className={cnState(dialogContentVariants({ size, sheet }), className)}
      finalFocus={returnFocus}
      {...props}
    >
      {wrap(children)}
    </DialogContentPrimitive>
  )
}

function DialogHeader({ className, render, ...props }: PartProps<"div">) {
  return renderElement(
    "div",
    { "data-slot": "dialog-header", className: cn("flex shrink-0 flex-col gap-inline", className), ...props },
    render,
  )
}

/**
 * The part that scrolls, so the header and footer stay in view; it clips the hidden inputs of Select and Checkbox.
 * Its scroll area reaches past the content's padding to its edges. Under `data-dialog-flush` the body drops its own
 * padding; a body that still wants its sides says so for that scope (`in-data-dialog-flush:px-inset-surface`).
 */
function DialogBody({ className, render, ...props }: PartProps<"div">) {
  return (
    <ScrollArea className="-mx-inset-surface flex min-h-0 min-w-0 flex-1 flex-col in-data-dialog-flush:mx-0">
      <ScrollAreaViewport
        render={(viewport) =>
          renderElement(
            "div",
            mergeProps(viewport, props, {
              "data-slot": "dialog-body",
              className: cn(
                "relative flex h-auto min-h-0 min-w-0 flex-1 flex-col gap-group overscroll-contain px-inset-surface in-data-dialog-flush:px-0",
                className,
              ),
            }),
            render,
          )
        }
      />
      <ScrollAreaScrollbar data-agent-hidden="" />
    </ScrollArea>
  )
}

function DialogFooter({ className, render, ...props }: PartProps<"div">) {
  return renderElement(
    "div",
    {
      "data-slot": "dialog-footer",
      className: cn("flex shrink-0 flex-col-reverse gap-items sm:flex-row sm:justify-end", className),
      ...props,
    },
    render,
  )
}

function DialogTitle({ className, ...props }: ComponentProps<typeof DialogTitlePrimitive>) {
  return <DialogTitlePrimitive className={cnState("text-title leading-none", className)} {...props} />
}

function DialogDescription({ className, ...props }: ComponentProps<typeof DialogDescriptionPrimitive>) {
  return <DialogDescriptionPrimitive className={cnState("text-sm text-muted-foreground", className)} {...props} />
}

function DialogClose({
  className,
  variant = "outline",
  size,
  tooltip,
  ...props
}: Omit<ComponentProps<typeof DialogClosePrimitive>, "aria-label"> & ButtonLookProps) {
  return (
    <ControlTooltip label={props["aria-label"]} tooltip={tooltip} iconOnly={size === "icon"}>
      <DialogClosePrimitive className={cnState(buttonVariants({ variant, size }), className)} {...props} />
    </ControlTooltip>
  )
}

export {
  Dialog,
  DialogBackdrop,
  DialogBody,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
  backdropClassName,
  contentClassName,
  createDialogController,
  dialogContentVariants,
  useFocusReturn,
}
export type { DialogContentProps, DialogSize }

"use client"

import { useEffect, useLayoutEffect, useRef, type RefObject } from "react"

type FocusMemory = { opener: HTMLElement | null; movedBeforeOpen: boolean }

function focusedElement() {
  const active = document.activeElement
  return active instanceof HTMLElement && active !== document.body ? active : null
}

function openModals() {
  const modals = [...document.querySelectorAll('[aria-modal="true"]')]
  try {
    modals.push(...document.querySelectorAll("dialog:modal"))
  } catch {
    // Engines without :modal (jsdom) still see modals by aria-modal.
  }
  return modals.filter((modal) => !modal.hasAttribute("data-ending-style"))
}

// A closing dialog gives focus back only from inside itself, or from <body> when no other modal is open. Another
// modal opened meanwhile (one of ours or another library's, which may move focus in a frame later) keeps it.
function mayReturnFocus(own: Element | null, active: Element | null = focusedElement()) {
  if (active) return own?.contains(active) ?? false
  return !openModals().some((modal) => modal !== own && !own?.contains(modal))
}

/** Records the focused element once, on mount. */
function useRecordOpener(memoryRef: RefObject<FocusMemory>) {
  const recorded = useRef(false)
  useLayoutEffect(() => {
    if (recorded.current) return
    recorded.current = true
    memoryRef.current = { opener: focusedElement(), movedBeforeOpen: false }
  }, [memoryRef])
}

/** Notes, once, whether focus moved away from the recorded opener between the two markers' layout effects. */
function useRecordFocusMove(memoryRef: RefObject<FocusMemory>) {
  const checked = useRef(false)
  useLayoutEffect(() => {
    if (checked.current) return
    checked.current = true
    memoryRef.current = { ...memoryRef.current, movedBeforeOpen: focusedElement() !== memoryRef.current.opener }
  }, [memoryRef])
}

/**
 * When the on-screen keyboard comes up, the content shrinks to the part of the page above it (`data-dialog-keyboard`
 * on a dialog's content, UI SDK's `data-keyboard` on a drawer's viewport), which can leave the field typed in below the fold of
 * the content's scroll area. Scrolls it back into view once the new size is laid out.
 */
function useFocusAboveKeyboard(contentRef: RefObject<HTMLElement | null>) {
  useEffect(() => {
    const viewport = window.visualViewport
    if (!viewport) return undefined
    let frame = 0
    const reveal = () => {
      cancelAnimationFrame(frame)
      frame = requestAnimationFrame(() => {
        const content = contentRef.current
        const active = focusedElement()
        if (active && content?.closest("[data-keyboard], [data-dialog-keyboard]") && content.contains(active)) {
          active.scrollIntoView({ block: "nearest", inline: "nearest" })
        }
      })
    }
    viewport.addEventListener("resize", reveal)
    return () => {
      cancelAnimationFrame(frame)
      viewport.removeEventListener("resize", reveal)
    }
  }, [contentRef])
}

function scrollLocked(element: Element) {
  return /hidden|clip/.test(getComputedStyle(element).overflow)
}

function pageLocked() {
  return scrollLocked(document.documentElement) || scrollLocked(document.body)
}

/**
 * Puts the page back where it was when something scrolls it while the dialog is open and the page is locked. WebKit
 * scrolls it for the text selection UI SDK makes in a field it focuses (0.1.0-beta.10, opening by controller, as
 * from a menu item), although the field is in a fixed dialog, so the page moves under the backdrop.
 */
function useKeepPageStill(contentRef: RefObject<HTMLElement | null>) {
  useEffect(() => {
    let x = window.scrollX
    let y = window.scrollY
    const restore = () => {
      if (contentRef.current?.hasAttribute("data-open") && pageLocked()) {
        if (window.scrollX !== x || window.scrollY !== y) window.scrollTo(x, y)
        return
      }
      x = window.scrollX
      y = window.scrollY
    }
    window.addEventListener("scroll", restore)
    return () => window.removeEventListener("scroll", restore)
  }, [contentRef])
}

export { focusedElement, mayReturnFocus, useFocusAboveKeyboard, useKeepPageStill, useRecordFocusMove, useRecordOpener }
export type { FocusMemory }

"use client"

import { useEffect, type RefObject } from "react"

const keyboardless = new Set([
  "button",
  "checkbox",
  "color",
  "file",
  "hidden",
  "image",
  "radio",
  "range",
  "reset",
  "submit",
])

function opensKeyboard(target: EventTarget | null) {
  let element = target instanceof Element ? target : null
  while (element?.shadowRoot?.activeElement) element = element.shadowRoot.activeElement
  if (!(element instanceof HTMLElement)) return false
  if (element.isContentEditable || element instanceof HTMLTextAreaElement || element instanceof HTMLIFrameElement) {
    return true
  }
  return element instanceof HTMLInputElement && !keyboardless.has(element.type)
}

const viewportProperties = ["--dialog-viewport-top", "--dialog-viewport-bottom", "--dialog-viewport-height"]

/** Where the properties go: the content, or its parent when that is what lays out against the page (a Drawer's viewport). */
type ViewportBoxScope = "content" | "parent"

// Writes the visual viewport for CSS to place against the containing block, not `innerHeight` (stale on iOS 26).
// Toolbars also shorten the visible part, where UI SDK's `data-keyboard` (beta.12) misfires, so `data-dialog-keyboard`
// also needs a focused field. Pinch-zoomed, the visual viewport is a window into the page: the last box stays.
function useVisualViewportBox(contentRef: RefObject<HTMLElement | null>, scope: ViewportBoxScope = "content") {
  useEffect(() => {
    const viewport = window.visualViewport
    if (!viewport) return undefined
    let pageScale = 1
    // Read on every update: a content rendered through `render` can attach its ref after this effect runs.
    let written: HTMLElement | null = null
    const clear = () => {
      for (const name of viewportProperties) written?.style.removeProperty(name)
      written?.removeAttribute("data-dialog-keyboard")
    }
    const update = (event?: Event) => {
      const content = scope === "parent" ? (contentRef.current?.parentElement ?? null) : contentRef.current
      if (content !== written) clear()
      written = content
      if (!content) return undefined
      if (Math.abs(viewport.height - window.innerHeight) <= 1) pageScale = viewport.scale
      if (viewport.scale > pageScale + 0.01) return undefined
      const bottom = viewport.offsetTop + viewport.height
      content.style.setProperty("--dialog-viewport-top", `${String(Math.round(viewport.offsetTop))}px`)
      content.style.setProperty("--dialog-viewport-bottom", `${String(Math.round(bottom))}px`)
      content.style.setProperty("--dialog-viewport-height", `${String(Math.round(viewport.height))}px`)
      const typing =
        opensKeyboard(document.activeElement) ||
        (event instanceof FocusEvent && event.type === "focusout" && opensKeyboard(event.relatedTarget))
      content.toggleAttribute("data-dialog-keyboard", typing && window.innerHeight - bottom > 1)
      return undefined
    }
    update()
    const frame = requestAnimationFrame(() => update())
    viewport.addEventListener("resize", update)
    viewport.addEventListener("scroll", update)
    window.addEventListener("resize", update)
    document.addEventListener("focusin", update)
    document.addEventListener("focusout", update)
    return () => {
      cancelAnimationFrame(frame)
      viewport.removeEventListener("resize", update)
      viewport.removeEventListener("scroll", update)
      window.removeEventListener("resize", update)
      document.removeEventListener("focusin", update)
      document.removeEventListener("focusout", update)
      clear()
    }
  }, [contentRef, scope])
}

export { useVisualViewportBox }
export type { ViewportBoxScope }
